B.aca=new A.S("sql-n2-1","Sin repetidos, con patrones","ORDER BY puede usar varias columnas: ordena por la primera y desempata con la segunda. DISTINCT quita las filas repetidas. LIKE busca patrones: % vale por cualquier texto.","SELECT DISTINCT ciudad FROM sospechosos ORDER BY ciudad\nSELECT nombre FROM sospechosos WHERE profesion LIKE 'c%'",B.alr,!1)
