B.b_W=new A.c(B.ap,"\xbfQu\xe9 sospechosos no tienen testigo? Muestra su sospechoso_id (tabla coartadas).",null,B.a,0,B.a,B.a,"SELECT sospechoso_id FROM coartadas WHERE testigo IS NULL",null,"","","",B.a,B.e,"",B.a,"WHERE testigo IS NULL","Los sospechosos 2 y 5 no tienen quien los respalde. Apunta esos n\xfameros.","","")
