B.abB=new A.S("sql-n2-2","Listas, rangos y vac\xedos","IN comprueba si un valor est\xe1 en una lista. BETWEEN a AND b incluye los dos extremos. Un valor vac\xedo es NULL y se busca con IS NULL (nunca con = NULL).","SELECT nombre FROM sospechosos WHERE ciudad IN ('Oviedo', 'Avil\xe9s')\nSELECT sospechoso_id FROM coartadas WHERE testigo IS NULL",B.awH,!1)
