B.aKp={ls:0,"cat config.ini":1,"authcfg --help":2,"authcfg --hash md5":3,"authcfg --hash sha1":4,"authcfg --hash argon2":5,"authcfg --hash bcrypt":6,"authcfg --max-intentos 5":7,"authcfg --mfa si":8}
